"""`.Hair highlight positioning`: generated by export_nodes.py from library.blend; kept by hand from then on."""

NAME = '.Hair highlight positioning'
KIND = 'ShaderNodeTree'


def build(lib):
    t = lib.new_group(NAME, KIND, props={})

    t.socket('OUTPUT', 'Vector', 'NodeSocketVector', min_value=0.0, max_value=0.0)

    t.node('NodeFrame', 'Frame.004', props={
        'location': (-197.36841, 166.0),
        'width': 290.0346,
        'height': 278.1053,
        'label': 'Hair highlight positioning',
    })
    t.node('ShaderNodeGroup', 'Group', parent='Frame.004', props={
        'node_tree': lib.group('Scale Vector'),
        'location': (29.397339, -39.627335),
        'width': 231.29776,
    })
    t.node('NodeGroupOutput', 'Group Output', props={
        'location': (187.03777, 94.24209),
    })
    t.node('ShaderNodeUVMap', 'hairuv', props={
        'location': (-413.15817, 69.855446),
        'width': 150.0,
        'uv_map': 'uv_nipple_and_shine',
    })

    t.link('hairuv', 'UV', 'Group', 'UV Map')
    t.link('Group', 'Coordinates', 'Group Output', 'Vector')
    return t
